package net.minecraft.client.renderer;import net.minecraft.resources.ResourceLocation;import ichttt.mods.firstaid.mixin.client.GameRendererPostAccessor;public class GameRenderer implements GameRendererPostAccessor{public PostChain effect;public int loads,shutdowns;public PostChain currentEffect(){return effect;}public void loadEffect(ResourceLocation id){shutdownEffect();loads++;effect=new PostChain(id.toString());}public void shutdownEffect(){shutdowns++;effect=null;}public void firstaid$loadEffect(ResourceLocation id){loadEffect(id);}public void firstaid$shutdownEffect(){shutdownEffect();}public PostChain firstaid$getPostEffect(){return effect;}}
